; Delays, pause and the game keys
; $809b-$813a

; Busy wait of 128 times X loop steps. Input: X. A does not change.
delay_short
        ldy #$80
delay_short_loop
        dex
        bne delay_short_loop
        dey
        bne delay_short_loop
        rts
; Busy wait of four short delays.
delay_long
