        jsr delay_short
        jsr delay_short
        jsr delay_short
        rts
; Busy wait that ends early when SPACE is pressed (key_row7 = $EF).
wait_or_space
        ldy #$90
wait_or_space_outer
        ldx #$00
wait_or_space_inner
        lda key_row7
        cmp #$ef
        bne wait_or_space_next
        rts
wait_or_space_next
        dex
        bne wait_or_space_inner
        dey
        bne wait_or_space_outer
